// Helper lookup index
const CURATED_LOOKUP = new Map<string, WordEntry[]>();

for (const entry of CURATED_WORDS) {
  const key = entry.word.toLowerCase();
  const list = CURATED_LOOKUP.get(key) || [];
  list.push(entry);
  CURATED_LOOKUP.set(key, list);
}

export function findCuratedWord(word: string, category: Category): WordEntry | undefined {
  const entries = CURATED_LOOKUP.get(word.toLowerCase().trim());
  if (!entries) return undefined;
  return entries.find(e => e.category === category);
}

export function getCuratedWordsForLetter(letter: string, category?: Category): WordEntry[] {
  const l = letter.toUpperCase();
  return CURATED_WORDS.filter(w => {
    const matchesLetter = w.word.toUpperCase().startsWith(l);
    if (!matchesLetter) return false;
    if (category && w.category !== category) return false;
    return true;
  });
}
